    in=basic();in.insert("rate_changes",QJsonArray{QJsonObject{{"date","2026-07-01"},{"rate","0.12"}}});in.insert("rate_change_policy","keep_payment");auto keep=runLoan("loanschedule",in);in.insert("rate_change_policy","recalculate");auto recast=runLoan("loanschedule",in);check(keep.tables[0].rows[5][6]==keep.tables[0].rows[6][6],"Keep-payment rate change retains regular amount");check(Real(recast.tables[0].rows[6][6])>Real(recast.tables[0].rows[5][6]),"Recalculate rate change increases next payment");
