    in=basic();in.insert("solve","payment");in.insert("payment","50");in.insert("horizon",3);r=runLoan("loansummary",in);check(r.status=="non_repaying","Constant payment below interest is proven non-repaying");in.insert("payment","61");r=runLoan("loansummary",in);check(r.status=="horizon","Small positive amortization at horizon is not called non-repayment");
    in=basic();in.insert("rounding","transaction");in.insert("precision",2);r=runLoan("loanschedule",in);qint64 paid=0,interest=0,principal=0;for(const auto&row:r.tables[0].rows){paid+=cents(row[6]);interest+=cents(row[4]);principal+=cents(row[8]);Real residue=Real(row[2])+Real(row[4])-Real(row[6])-Real(row[7])-Real(row[9]);if(residue!=Real(0))std::cout<<"INFO binary representation residue="<<residue.str(12).toStdString()<<"; exact printed row="<<row.join(" | ").toStdString()<<'\n';check(cents(row[2])+cents(row[4])-cents(row[6])-cents(row[7])==cents(row[9]),"Rounded schedule row reconciles in exact integer minor units");}check(principal==1200000,"Rounded schedule principal sums to original balance in integer cents");check(paid==cents(value(r,"Total scheduled repayments"))&&interest==cents(value(r,"Total interest")),"Rounded schedule totals reconcile in exact integer minor units");
    in=basic();in.insert("amount","100");in.insert("rate","0");in.insert("term",3);in.insert("rounding","transaction");in.insert("precision",0);r=runLoan("loansummary",in);check(value(r,"Final payment incl. extra (excluding fees)")=="34","Zero-decimal money final remainder is adjusted");
    QJsonObject credit{{"amount","1000"},{"rate","0.12"},{"minimum_rule","balance_percent"},{"minimum_percent","0.02"},{"fixed_minimum","10"},{"fixed_payment","100"},{"extra_payment","50"},{"balance_basis","before_interest_fees"},{"horizon",1200},{"precision",2},{"rounding","transaction"}};r=runLoan("creditpayoff",credit);check(r.tables.size()==3,"Credit comparison supplies all three complete schedules");check(r.tables[0].rows[0][6]=="20.00","Minimum percentage uses explicit before-interest balance");credit.insert("balance_basis","after_interest_fees");r=runLoan("creditpayoff",credit);check(r.tables[0].rows[0][6]=="20.20","Minimum percentage uses explicit after-interest balance");credit.insert("minimum_rule","principal_plus_costs");credit.insert("balance_basis","before_interest_fees");r=runLoan("creditpayoff",credit);check(r.tables[0].rows[0][6]=="30.00","Principal percentage plus current interest");check(r.tables[2].rows[0][6]=="80.00","Minimum plus extra rule");
    credit.insert("fixed_payment","5");r=runLoan("creditpayoff",credit);check(value(r,"Fixed payment — status")=="Proven non-repaying","Credit fixed payment below interest identified as proven");credit.insert("fixed_payment","11");credit.insert("horizon",1);r=runLoan("creditpayoff",credit);check(value(r,"Fixed payment — status").startsWith("Horizon reached"),"Credit horizon does not prove non-repayment");
